import {ownerStyles,ownerScript} from './owner_design.ts';
import {approvalInboxStyles,approvalInboxScript} from './approval_inbox.ts';
import {themeInit,themeScript,themeButton,themeStyles} from './portal_theme.ts';
import {brandDiagram,brandDiagramStyles,circularBrandStyles,compactSignInStyles} from './brand_diagram.ts';
import {escaped} from './policy.ts';

export interface PortalDevice {id:string;name:string;created:number;revoked:boolean;lastSeen:number;online?:boolean;os?:string;agentVersion?:string;capabilities?:string[];calls?:number;}
export interface PortalData {active?:string;devices:PortalDevice[];calls:number;monthly:{used:number;limit:number;resetsAt:number};plan?:'free'|'pro';billing?:{id:string;status:string;cancelAt?:string|null}[];usage?:{started:number;days:Record<string,number>};activity?:{at:number;deviceId:string;tool:string;outcome:string;durationMs:number}[];}
export interface PortalOwner {login:string;csrf:string;userId?:string;}
const paths:Record<string,string>={backups:'M4 5h16v14H4zM8 9h8M8 13h8M8 17h4',devices:'M3 4h18v12H3zM8 21h8M12 16v5',usage:'M4 20V11M10 20V4M16 20v-7M22 20H2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',plan:'M3 5h18v14H3zM3 9h18M6 15h4',plus:'M12 5v14M5 12h14',arrow:'M5 12h14M13 6l6 6-6 6',shield:'M12 2l8 3v6c0 5-8 11-8 11S4 16 4 11V5zM8 11l3 3 5-6',check:'M5 12l4 4L19 6',copy:'M8 8h13v13H8zM16 8V3H3v13h5',external:'M14 3h7v7M21 3l-9 9M10 3H3v18h18v-7',back:'M19 12H5M11 6l-6 6 6 6'};
export const icon=(name:string)=>'<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="'+(paths[name]??paths.devices)+'"/></svg>';
export const button=(label:string,variant='primary',attrs='')=>'<button type="submit" class="button '+variant+'" '+attrs+'>'+label+'</button>';
export const hidden=(name:string,value:string)=>'<input type="hidden" name="'+escaped(name)+'" value="'+escaped(value)+'">';
export const isOnline=(d:PortalDevice)=>d.online??(d.lastSeen>Date.now()/1000-180);
const number=(n:number)=>Number(n||0).toLocaleString('en-US');

