const script=String.raw`
(()=>{
  const setupDialog=document.querySelector('[data-setup-dialog]');
  const setupTitle=setupDialog?.querySelector('#setup-dialog-title');
  const osSwitch=document.querySelector('.os-switch');
  function showSetupStage(stage,title){
    if(!setupDialog)return;
    setupDialog.dataset.stage=stage;
    setupTitle.textContent=title;
    osSwitch.hidden=stage!=='choose'&&stage!=='run';
    if(stage!=='assistant')setupDialog.querySelectorAll('video').forEach(video=>video.pause());
    for(const panel of setupDialog.querySelectorAll('[data-setup-panel]'))panel.hidden=panel.dataset.setupPanel!==stage;
    for(const item of setupDialog.querySelectorAll('[data-setup-progress]')){
      if(item.dataset.setupProgress===stage)item.setAttribute('aria-current','step');
      else item.removeAttribute('aria-current');
    }
    setupDialog.scrollTop=0;
    setupTitle.focus({preventScroll:true});
  }
  if(setupDialog){
    setupDialog.removeAttribute('open');
    setupDialog.showModal();
    setupDialog.addEventListener('close',()=>location.assign('/devices'));
    setupDialog.addEventListener('click',event=>{
      const link=event.target.closest('[data-setup-stage],[data-setup-client]');
      if(!link||event.button!==0||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey)return;
      event.preventDefault();
      if(link.dataset.setupStage){
        const stage=link.dataset.setupStage;
        showSetupStage(stage,{choose:'Connect this device',assistant:'Connect your AI assistant',verify:'Verify your computer'}[stage]);
      }else{
        const client=link.dataset.setupClient;
        for(const panel of setupDialog.querySelectorAll('[data-assistant-panel]')){
          panel.hidden=panel.dataset.assistantPanel!==client;
          if(panel.hidden)panel.querySelector('video')?.pause();
          else panel.querySelector('[aria-current="page"]').focus({preventScroll:true});
        }
      }
    });
    setupDialog.querySelector('[data-setup-back]').addEventListener('click',()=>showSetupStage('choose','Connect this device'));
    setupDialog.querySelector('[download]').addEventListener('click',()=>{
      setupDialog.querySelector('[data-run-open]').textContent='Open the downloaded Start-PCRC.cmd file.';
      setupDialog.querySelector('[data-run-paste]').textContent='Double-click it and keep its window open.';
      showSetupStage('run','Run Start-PCRC.cmd');
    });
  }
  if(osSwitch)osSwitch.addEventListener('click',event=>{
    const link=event.target.closest('a[data-os]');
    if(!link||event.button!==0||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey)return;
    event.preventDefault();
    for(const tab of osSwitch.querySelectorAll('a[data-os]')){
      const active=tab===link;
      if(active)tab.setAttribute('aria-current','page');
      else tab.removeAttribute('aria-current');
      document.getElementById('setup-'+tab.dataset.os).hidden=!active;
    }
    history.replaceState(history.state,'',link.href);
    if(setupDialog?.dataset.stage!=='choose')showSetupStage('choose','Connect this device');
  });
  document.querySelectorAll('[data-copy-target]').forEach(button=>button.addEventListener('click',async()=>{
    const target=document.getElementById(button.dataset.copyTarget);if(!target)return;
    try{
      const label=button.value;
      await navigator.clipboard.writeText(target.textContent.trim());
      button.value='Copied';setTimeout(()=>{button.value=label;},1800);
      if(setupDialog?.querySelector('[data-setup-panel="choose"]').contains(button)){
        const platform=osSwitch.querySelector('[aria-current="page"]').dataset.os;
        const instructions={
          windows:['Paste this in PowerShell','Open PowerShell from the Start menu.','Press Ctrl+V, then Enter.'],
          macos:['Paste this in Terminal','Press Command+Space, search for Terminal, and open it in the PCRC source folder.','Press Command+V, then Return.'],
          linux:['Paste this in Terminal','Open Terminal from your apps menu and switch to the PCRC source folder.','Press Ctrl+Shift+V, then Enter.']
        }[platform];
        setupDialog.querySelector('[data-run-open]').textContent=instructions[1];
        setupDialog.querySelector('[data-run-paste]').textContent=instructions[2];
        showSetupStage('run',instructions[0]);
      }
    }
    catch{const range=document.createRange();range.selectNodeContents(target);const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);button.value='Copy selected text';}
  }));
  document.querySelectorAll('form[data-mutation]').forEach(form=>form.addEventListener('submit',event=>{
    if(form.dataset.busy){event.preventDefault();return;}form.dataset.busy='1';
    form.querySelectorAll('button').forEach(button=>{button.setAttribute('aria-disabled','true');button.classList.add('busy');});
  }));
  window.addEventListener('pageshow',()=>document.querySelectorAll('form[data-mutation]').forEach(form=>{delete form.dataset.busy;form.querySelectorAll('button').forEach(button=>{button.removeAttribute('aria-disabled');button.classList.remove('busy');});}));
  document.querySelectorAll('time[datetime]').forEach(el=>{const date=new Date(el.dateTime);if(!Number.isNaN(date.getTime()))el.textContent=new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(date);});
  const welcome=document.getElementById('pro-welcome');if(welcome){welcome.showModal();welcome.querySelector('button').focus();welcome.querySelector('button').addEventListener('click',()=>welcome.close());history.replaceState(null,'',location.pathname);}
  const live=document.getElementById('live-status');if(!live)return;
  const pairingStarted=new URLSearchParams(location.search).get('notice')==='approved'?Date.now():null;
  let timer,controller,stopped=false,errors=0;
  async function refresh(){
    if(stopped||document.hidden)return;
    controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),8000);
    try{
      const response=await fetch('/devices/state',{credentials:'same-origin',cache:'no-store',signal:controller.signal});
      if(response.status===401||response.status===403){stopped=true;live.textContent='Session expired. Sign in again.';return;}
      if(!response.ok)throw Error();const data=await response.json();errors=0;
      const dashboard=document.querySelector('.dashboard-layout');if(dashboard&&(data.plan!==dashboard.dataset.plan||JSON.stringify(data.billing??[])!==dashboard.dataset.billingState)){location.reload();return;}
      const ids=data.devices.filter(d=>!d.revoked).map(d=>d.id).sort().join(',');
      if(document.body.dataset.deviceIds!==undefined&&ids!==document.body.dataset.deviceIds){location.reload();return;}
      data.devices.forEach(d=>{const row=document.querySelector('[data-device-id="'+d.id+'"]');if(!row)return;const online=d.online===undefined?d.lastSeen>data.measuredAt/1000-180:d.online;const state=row.querySelector('[data-presence]');if(state){state.classList.toggle('online',online);state.lastChild.textContent=online?'Online':'Offline';}});
      document.querySelectorAll('[data-call-count]').forEach(el=>{el.textContent=Number(data.calls||0).toLocaleString();});
      if(data.monthly){document.querySelectorAll('[data-month-used]').forEach(el=>{el.textContent=Number(data.monthly.used).toLocaleString();});document.querySelectorAll('[data-month-remaining]').forEach(el=>{el.textContent=Math.max(0,data.monthly.limit-data.monthly.used).toLocaleString();});document.querySelectorAll('[data-month-progress]').forEach(el=>{el.value=Math.min(data.monthly.used,data.monthly.limit);});document.querySelectorAll('.usage-ring[role=img]').forEach(el=>{el.style.setProperty('--used',Math.min(100,Math.max(0,data.monthly.used/data.monthly.limit*100))+'%');el.setAttribute('aria-label',Number(data.monthly.used).toLocaleString()+' of '+Number(data.monthly.limit).toLocaleString()+' monthly calls used');});}
      const active=document.querySelector('[data-device-id][data-selected="true"]')?.dataset.deviceId;
      if(active!==data.active&&(active||data.active)){location.reload();return;}
      live.textContent='Live status · updated just now';
    }catch{if(!document.hidden){errors++;live.textContent='Status may be out of date. Refresh to retry.';}}
    finally{clearTimeout(timeout);if(!stopped)timer=setTimeout(refresh,Math.min((pairingStarted!==null&&Date.now()-pairingStarted<60000?2000:10000)*Math.max(1,errors),60000));}
  }
  document.addEventListener('visibilitychange',()=>{clearTimeout(timer);if(document.hidden)controller?.abort();else refresh();});
  window.addEventListener('pagehide',()=>{stopped=true;clearTimeout(timer);controller?.abort();});
  refresh();
})();`;

export const trackingCleanupScript=String.raw`window.addEventListener('load', () => {
  const url = new URL(window.location.href);
  let changed = false;
  for (const name of ['utm_source', 'utm_medium', 'utm_campaign', 'utm_content', 'utm_term', 'fbclid', 'gclid']) {
    if (url.searchParams.has(name)) {
      url.searchParams.delete(name);
      changed = true;
    }
  }
  if (changed) {
    window.history.replaceState(window.history.state, '', url.pathname + url.search + url.hash);
  }
}, { once: true });`;


